use std::{collections::HashMap,fs,path::{Path,PathBuf},sync::{Mutex,OnceLock},time::{Duration,Instant}};
use std::os::unix::fs::MetadataExt;
struct Grant {operation:String,path:PathBuf,dir:fs::File,dev:u64,ino:u64,until:Instant}
static GRANTS:OnceLock<Mutex<HashMap<String,Grant>>>=OnceLock::new();
fn state()->&'static Mutex<HashMap<String,Grant>>{static CLEANER:std::sync::Once=std::sync::Once::new();let state=GRANTS.get_or_init(||Mutex::new(HashMap::new()));CLEANER.call_once(||{std::thread::spawn(||loop{std::thread::sleep(Duration::from_secs(1));if let Some(state)=GRANTS.get(){if let Ok(mut grants)=state.lock(){grants.retain(|_,v|v.until>Instant::now());}}});});state}
pub fn issue(operation:&str,path:&Path)->Result<String,String>{if !matches!(operation,"import"|"export")||!path.is_absolute()||path.is_symlink()||!path.is_dir(){return Err("invalid selection".into())}let path=path.canonicalize().map_err(|e|e.to_string())?;use std::os::unix::fs::OpenOptionsExt;let dir=fs::OpenOptions::new().read(true).custom_flags(libc::O_DIRECTORY|libc::O_NOFOLLOW).open(&path).map_err(|e|e.to_string())?;let meta=dir.metadata().map_err(|e|e.to_string())?;let value=uuid::Uuid::new_v4().simple().to_string();#[cfg(feature="test-hook")] let ttl=std::env::var("ATLAS_TEST_PORTABLE_CAP_TTL_MS").ok().and_then(|v|v.parse().ok()).map(Duration::from_millis).unwrap_or(Duration::from_secs(300));#[cfg(not(feature="test-hook"))] let ttl=Duration::from_secs(300);let mut grants=state().lock().map_err(|_|"selection unavailable")?;grants.retain(|_,v|v.until>Instant::now());if grants.len()>=64{return Err("too many selections".into())}grants.insert(value.clone(),Grant{operation:operation.into(),path,dir,dev:meta.dev(),ino:meta.ino(),until:Instant::now()+ttl});Ok(value)}
pub fn consume(operation:&str,value:&str)->Result<(PathBuf,fs::File),String>{let g=state().lock().map_err(|_|"selection unavailable")?.remove(value).ok_or("selection expired")?;if g.operation!=operation||g.until<=Instant::now()||g.path.is_symlink(){return Err("selection unavailable".into())}let meta=fs::metadata(&g.path).map_err(|_|"selection unavailable")?;if meta.dev()!=g.dev||meta.ino()!=g.ino||!meta.is_dir(){return Err("selection changed".into())}Ok((g.path,g.dir))}
pub fn revoke(value:&str){if let Ok(mut grants)=state().lock(){grants.remove(value);}}
#[cfg(test)]mod tests {use super::*;
 #[test]fn bound_single_use_and_operation(){let p=std::env::temp_dir();let token=issue("import",&p).unwrap();assert!(consume("export",&token).is_err());assert!(consume("import",&token).is_err());let token=issue("import",&p).unwrap();assert_eq!(consume("import",&token).unwrap().0,p.canonicalize().unwrap());assert!(consume("import",&token).is_err());}
 #[test]fn replaced_directory_rejected(){let root=std::env::temp_dir().join(format!("atlas-capability-{}",uuid::Uuid::new_v4()));fs::create_dir(&root).unwrap();let original=root.join("chosen");fs::create_dir(&original).unwrap();let token=issue("export",&original).unwrap();fs::rename(&original,root.join("old")).unwrap();fs::create_dir(&original).unwrap();assert!(consume("export",&token).is_err());fs::remove_dir_all(root).unwrap();}
}
